#include <bits/stdc++.h>
using namespace std;

long long pow_mod(long long base, int exp, long long mod) {
    long long result = 1;
    long long cur = base % mod;
    for (int i = 0; i < exp; i++) {
        result = (result * cur) % mod;
    }
    return result;
}

long long modularInverse(long long a, long long m) {
    return pow_mod(a, (int)m - 2, m);
}

